<?php
$h = static fn($value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$categoryIcons = ['tecnologia'=>'▱','vivienda'=>'⌂','vehiculos'=>'▰','hogar y oficina'=>'▤','servicios'=>'⚒','mascotas'=>'♧','deportes y ocio'=>'◉','libros y educación'=>'▣','otros'=>'•••'];
$relativeDate = static function ($date): string {
    if (!$date) return 'Fecha no disponible';
    $seconds = max(0, time() - strtotime((string)$date));
    if ($seconds < 3600) return 'Hace ' . max(1, (int)floor($seconds / 60)) . ' min';
    if ($seconds < 86400) return 'Hace ' . max(1, (int)floor($seconds / 3600)) . ' horas';
    return 'Hace ' . max(1, (int)floor($seconds / 86400)) . ' días';
};
